/**
 * Match recaps at half-time and at the replay point, generated by matchdesk.domain.recap_feed.
 * Every figure in a recap comes from a claim the verifier passed; the page re-runs those checks.
 */
import feed from "./generated/nbr-riv-recaps.json";
import type { Recap, RecapClaim } from "./recap-chrome";

const data = feed as unknown as { recaps: Recap[]; claims: RecapClaim[]; replay_end_ms: number; match_id: string };

export const recaps: readonly Recap[] = data.recaps;
export const recapClaims: readonly RecapClaim[] = data.claims;
export const recapMatchId = data.match_id;
export const recapReplayEndMs = data.replay_end_ms;
